#!/usr/bin/env python3
from pathlib import Path
import json,csv,hashlib,zipfile
ROOT=Path(__file__).resolve().parent
report=json.loads((ROOT/'validation_report.json').read_text());overlay=json.loads((ROOT/'normalized_confirmation_overlay.json').read_text());audit=json.loads((ROOT/'independent_audit.json').read_text())
selected=[r for r in report['rows'] if r['normalized_included']]
with (ROOT/'confirmed_geometry_deltas.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['image_code','confirmation_basis','decision','comparison_baseline','old_vertices','new_vertices','old_area_h2','new_area_h2','area_delta_h2','symmetric_difference_area_h2','max_matched_gt_normal_distance_h','camera_boundary_min_distance_h'])
    for r in selected:
        d=r['previous_confirmation_geometry_delta'] or r['baseline_geometry_delta']
        w.writerow([r['image_code'],r['status'],r['decision'],'previous_confirmation' if r['previous_confirmation_geometry_delta'] else 'editing_GT_floor',d['old_vertices'],d['new_vertices'],d['old_area_h2'],d['new_area_h2'],d['area_delta_h2'],d['symmetric_difference_area_h2'],r['gt_snap_max_final_normal_distance_h'],r['camera_boundary_min_distance_h']])
with (ROOT/'gt_edge_residuals.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['image_code','manual_edge_zero_based','gt_edge_zero_based','max_final_normal_distance_h','finite_overlap_h','signed_mean_normal_offset_h','half_line_error_h','literal_exact_parallel','stored_pre_snap_distance_px'])
    for r in selected:
        for e in r['gt_snap_edges']:
            w.writerow([r['image_code'],e['edge'],e['gt_edge'],e['actual_final_max_normal_distance_h'],e['actual_final_finite_overlap_h'],e['actual_final_signed_mean_normal_offset_h'],e['actual_final_half_line_error_h'],e['actual_final_exact_parallel'],e['distance_px']])
with (ROOT/'all_259_audit.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['image_code','source_pointer','status','provenance_exact','valid','camera_inside','operation_count','decision','raw_completed','raw_floor_region_confirmed','raw_updated_at','normalized_included'])
    for r in report['rows']:w.writerow([r[k] for k in ['image_code','source_pointer','status','provenance_exact','valid','camera_inside','operation_count','decision','raw_completed','raw_floor_region_confirmed','raw_updated_at','normalized_included']])
lines=['# 最新空间范围回执校验（2026-10-10）','','## 结论','','校验通过。可确认并接回 16 张底面范围：5 张此前已确认、此次修改后忘记点击确认的图，依据用户聊天明确确认；11 张新图保留导出文件中的按钮确认。用户随后明确将旧图数量更正为 5 张，因此没有待猜测的第 6 张。','','- 13 张采用用户画出的矩形；3 张接受完整编辑基准底面：S9hNv5qa7GM-04、pa4otMbVnkk-14、wc2JMjhGNzB-26。','- 259 条导出记录逐一通过身份、GT、版本、证据来源和操作回放检查；其余 243 条是未编辑的默认草稿，不予新增确认。','- Site 共 280 个目录条目，其中 21 个历史条目没有可编辑参考点且不在当前语料，按现有导出逻辑不进入这份 259 条回执。','- 所有确认仍只针对底面；top_boundary_pending=true、reference_ready=false、formal_eligibility_changed=false。原始/当前 GT、顶面、资格门禁和评分均未由本校验修改。','','## 来源与时间','','- 用户原始附件：空间范围人工审核_2026-10-10(2).json','- 导出时间：2026-10-10T11:52:40.335Z','- SHA256：'+overlay['source']['receipt_sha256'],'- 明确确认消息：Sentinel_9ed00ac0b1388191a64819aae866107b，2026-10-10T11:53:17Z。','- 数量更正消息：Sentinel_b0471b82acec8191b2289d5f76e245bd，2026-10-10T11:56:26Z：“那就是之前审核的5张.”','- 编辑参考来源提交：'+overlay['source_commit'],'- 最新范围意见来源提交：'+overlay['latest_scope_review_source_commit'],'- 图证来源提交：'+overlay['evidence_source_commit'],'','原始回执逐字节保留在 inputs/raw_scope_receipt.json。5 张旧图的 completed=false 仍保留在原始文件；规范化层记录后来聊天确认的依据与时间，不伪造按钮操作。11 张新图保留原按钮确认时间。旧 Site 确认和回执内确认快照完整保留在每条记录的 previous_confirmation_history。','','## 双重校验','','1. 使用随包冻结的 Site geometry.js 与 review-state.js 校验完整导出 schema、259 条身份及编辑/历史 GT 对应、提交来源、原旧快照、全部操作和每步几何有效性。','2. 使用独立 Python 标准库实现再次检查 JSON 重复键/非有限数、ERP 投影、线段相交、绕数法相机包含、矩形回放和规范化坐标/来源保真。','3. 518 个原始/当前多边形全部有效，相机严格在内，259 个草稿全部可回放，16 条规范化记录坐标逐项精确保留。','4. 原始 ERP GT 点与 Site 完全一致。88 个底面投影跨浏览器/Node 运算存在最多 8.881784197001252e-16 的浮点尾差，独立 Python 最多 1.3322676295501878e-15；均远小于现有验证容差 1e-8。规范化输出使用回执原坐标，不用重算结果覆盖。','','## 几何变化','','旧 5 图与各自上一确认版本比较；新 11 图与编辑基准 GT 底面比较。面积单位是相机高度的平方（h²），距离单位是相机高度（h）。这些只是几何差量，不是质量分、IoU 排名或资格裁决。','','| 图号 | 确认方式 | 结论 | 旧面积 h² | 新面积 h² | 面积差 h² | 匹配 GT 边最大残差 h |','|---|---|---|---:|---:|---:|---:|']
for r in selected:
    d=r['previous_confirmation_geometry_delta'] or r['baseline_geometry_delta'];res=r['gt_snap_max_final_normal_distance_h']
    lines.append(f"| {r['image_code']} | {'聊天补确认' if r['previous_confirmation_geometry_delta'] else '按钮'} | {r['decision']} | {d['old_area_h2']:.9g} | {d['new_area_h2']:.9g} | {d['area_delta_h2']:.9g} | {res:.9g} |" if res is not None else f"| {r['image_code']} | 按钮 | {r['decision']} | {d['old_area_h2']:.9g} | {d['new_area_h2']:.9g} | 0 | 不适用 |")
lines+=['','## GT 边线贴合解释','','13 个修改区都记录为 rectangle，没有 gt_follow 操作。51 组吸附匹配都标记 exact=false，但这描述的是 GT 原边与严格矩形的微小非平行性，不代表用户范围无效，也不支持自动改动或拒收。最终匹配边的最大法向残差仅 0.00015609846532389424 h。','', '残差按当前用户边与指定 GT 边的有限重叠段计算：将 GT 边投影到用户边的切向坐标，取实际有限重叠区间两端的最大绝对法向距离；保留非平行角度和重叠长度检查。它不是整条延长线或整个房间边界的 Hausdorff 距离。gt_snap.distance_px 是吸附前、按当时视口比例计算的距离，不能当作吸附后的残差。','','- pRbA3pwrgk9-02：下侧 z 从旧确认 -0.3376472492951668 移到 -0.3335073958350185。与 GT 第 5 号边（0 起始）实际重叠段的最大法向残差从 0.004141406815682147 h 降至 0.0000015760676835660342 h；右侧 x 也从 0.35473335852901305 收到 0.33367062726686236，按用户回执原样保留。','- q9vSo1VnCiC-12：下侧 z=-2.665796884092004，与 GT 第 7 号边最大法向残差 0.00003484569054013065 h；全图匹配边最大残差 0.0000515628349297395 h。此图此前无确认手工区域，不能凭这份回执捏造“旧手工下边界”。','- 未吸附边仍是用户明确确认的手工边，不能自动替换为 GT。','','## 文件与复现','','- normalized_confirmation_overlay.json：仅 16 条明确确认的规范化底面叠加层，schema=manual_floor_scope_confirmation_overlay_v1。','- validation_report.json / independent_audit.json：完整逐条校验结果。','- confirmed_geometry_deltas.csv：16 图几何变化。','- gt_edge_residuals.csv：51 个匹配边的最终实测残差。','- all_259_audit.csv / unchanged_243_image_codes.json：完整范围与未动记录名单。','- inputs/：原始回执与冻结的校验代码、Site 数据；不是修改后的 Site。','','在本目录运行：','','```sh','node validate_receipt.js','python independent_audit.py','python build_reports.py','```','','本报告验证来源一致性、用户确认状态和几何可回放性；不替代原图语义审查，也不宣称顶面或 3D 房间参考已经验收。']
(ROOT/'REPORT.md').write_text('\n'.join(lines)+'\n')
manifest={str(p.relative_to(ROOT)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size} for p in sorted(ROOT.rglob('*')) if p.is_file() and p.name!='manifest.json'}
(ROOT/'manifest.json').write_text(json.dumps({'schema':'scope_receipt_bundle_manifest_v1','files':manifest},indent=2)+'\n')
zip_path=ROOT.parent/'latest_scope_receipt_validation_20261010.zip'
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted(ROOT.rglob('*')):
        if p.is_file():z.write(p,str(p.relative_to(ROOT.parent)))
print(json.dumps({'zip_path':str(zip_path),'zip_bytes':zip_path.stat().st_size,'zip_sha256':hashlib.sha256(zip_path.read_bytes()).hexdigest(),'overlay_sha256':hashlib.sha256((ROOT/'normalized_confirmation_overlay.json').read_bytes()).hexdigest(),'bundle_files':len(manifest)+1},indent=2))
